<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { CalendarDays, ChevronDown, ChevronLeft, ChevronRight, Columns3, GanttChart, GripVertical, RefreshCw } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import Pager from '../components/Pager.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import { useConflict } from '../drafts'
import { api, dateLabel, isArchived, localDate, messageOf, notify, taskStatuses, ui } from '../api'
import { dateNumber, dayString, filterTree, taskSpan, timelineWindow, dayMs } from '../progress'
import type { Page, Task } from '../types'
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[];task:[id:string]}>()
const project=ref(''),tasks=ref<Task[]>([]),loading=ref(false),error=ref(''),view=ref('gantt'),search=ref(''),status=ref(''),assignee=ref(''),anchor=ref(localDate()),zoom=ref('week'),collapsed=ref<string[]>([]),offset=ref(0),changing=ref<Task>(),nextStatus=ref('doing'),reason=ref(''),saving=ref(false),changeError=ref(''),boardDrag=ref<Task>(),calendarSelected=ref<{date:string;tasks:Array<{task:Task;ancestor:boolean}>}>(),calendarOffset=ref(0),boardLimits=ref<Record<string,number>>({}),conflict=useConflict();const limit=200
const filtering=computed(()=>!!(search.value.trim()||status.value||assignee.value)),people=computed(()=>[...new Set(tasks.value.map(t=>t.assignee).filter(Boolean))].sort()),rows=computed(()=>filterTree(tasks.value,search.value,status.value,assignee.value,view.value==='board'?new Set<string>():new Set(collapsed.value))),visibleRows=computed(()=>rows.value.slice(offset.value,offset.value+limit)),missing=computed(()=>rows.value.filter(({task})=>!taskSpan(task).valid)),leaves=computed(()=>rows.value.filter(({task})=>!task.has_children))
const statuses=['todo','doing','done','canceled'] as const
const timeline=computed(()=>timelineWindow(anchor.value,zoom.value)),days=computed(()=>Array.from({length:timeline.value.count},(_,i)=>{const number=timeline.value.start+i,date=new Date(number*dayMs);return{number,label:`${date.getUTCMonth()+1}/${date.getUTCDate()}`,weekend:[0,6].includes(date.getUTCDay()),today:number===dateNumber(localDate()),monthStart:date.getUTCDate()===1}})),timelineWidth=computed(()=>timeline.value.count*timeline.value.cell)
const calendarDays=computed(()=>{const number=dateNumber(anchor.value);const date=new Date((Number.isFinite(number)?number:dateNumber(localDate()))*dayMs);const first=Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),1)/dayMs;const weekday=(new Date(first*dayMs).getUTCDay()+6)%7;return Array.from({length:42},(_,i)=>{const day=first-weekday+i,d=new Date(day*dayMs);return{day,label:d.getUTCDate(),date:dayString(day),outside:d.getUTCMonth()!==date.getUTCMonth(),today:day===dateNumber(localDate()),tasks:rows.value.filter(({task})=>{const span=taskSpan(task);return span.valid&&day>=span.start&&day<=span.end})}})})
const monthTitle=computed(()=>(anchor.value||localDate()).slice(0,7).replace('-',' 年 ')+' 月')
function columns(status:string){return leaves.value.filter(row=>row.task.status===status)}
function openCalendarDay(day:{date:string;tasks:Array<{task:Task;ancestor:boolean}>}){calendarSelected.value={date:day.date,tasks:day.tasks};calendarOffset.value=0}
let loadRequest=0
async function load(){const request=++loadRequest,pid=project.value;error.value='';if(!pid){tasks.value=[];loading.value=false;return}loading.value=true;try{const page=await api<Page<Task>>(`/api/projects/${pid}/tree`);if(request===loadRequest)tasks.value=page.items}catch(e){if(request===loadRequest)error.value=messageOf(e)}finally{if(request===loadRequest)loading.value=false}}
function toggle(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(v=>v!==id):[...collapsed.value,id]}
function expandAll(){collapsed.value=[]}function foldAll(){collapsed.value=tasks.value.filter(t=>t.has_children).map(t=>t.id)}
function shift(direction:number){const raw=dateNumber(anchor.value),value=Number.isFinite(raw)?raw:dateNumber(localDate()),d=new Date(value*dayMs);if(view.value==='calendar'||zoom.value==='month'){d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+direction);anchor.value=d.toISOString().slice(0,10)}else anchor.value=dayString(value+direction*(zoom.value==='day'?7:28))}
function barStyle(task:Task,actual=false){const span=taskSpan(task,actual),window=timeline.value;if(!span.valid)return{};const start=Math.max(span.start,window.start),end=Math.min(span.end,window.start+window.count-1);return{left:`${(start-window.start)*window.cell+3}px`,width:`${Math.max(5,(end-start+1)*window.cell-6)}px`}}
function inWindow(task:Task,actual=false){const span=taskSpan(task,actual);return span.valid&&span.end>=timeline.value.start&&span.start<timeline.value.start+timeline.value.count}
function pointStyle(value:string){return{left:`${(dateNumber(value)-timeline.value.start)*timeline.value.cell+timeline.value.cell/2}px`}}
function pointInWindow(value:string){const n=dateNumber(value);return Number.isFinite(n)&&n>=timeline.value.start&&n<timeline.value.start+timeline.value.count}
function editStatus(task:Task,to=''){if(task.has_children||isArchived(task.project_id))return;changing.value=task;nextStatus.value=to||task.status;reason.value='';changeError.value='';conflict.clear()}
async function saveStatus(){const task=changing.value;if(!task||saving.value)return;const reopening=task.status==='done';if(reopening&&!reason.value.trim()){changeError.value='请填写重开原因';return}if(!reopening&&task.status===nextStatus.value){changing.value=undefined;return}saving.value=true;changeError.value='';try{await api<Task>(`/api/tasks/${task.id}${reopening?'/reopen':''}`,{method:reopening?'POST':'PATCH',body:JSON.stringify(reopening?{version:task.version,reason:reason.value,progress:0}:{version:task.version,status:nextStatus.value})});changing.value=undefined;notify(reopening?'任务已按原因重开为进行中':'任务状态已更新');emit('changed');await load()}catch(e){changeError.value=messageOf(e);await conflict.capture(e,`/api/tasks/${task.id}`,{status:nextStatus.value})}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as Task;if(!remote)return;changing.value=remote;nextStatus.value=remote.status;conflict.clear();changeError.value='已载入最新状态，请核对后操作。';await load()}
function drag(event:DragEvent,task:Task){if(task.has_children||['done','canceled'].includes(task.status)||isArchived(task.project_id)){event.preventDefault();return}boardDrag.value=task;event.dataTransfer?.setData('text/plain',task.id)}
function drop(event:DragEvent,to:string){event.preventDefault();const task=boardDrag.value;boardDrag.value=undefined;if(task&&task.status!==to)editStatus(task,to)}
function page(next:number){offset.value=next}
onMounted(()=>{project.value=ui.projects.find(p=>p.status==='active')?.id||ui.projects[0]?.id||''});watch(project,()=>{collapsed.value=[];offset.value=0;void load()});watch(()=>props.revision,load);watch([search,status,assignee,view],()=>{offset.value=0});watch(()=>rows.value.length,total=>{if(offset.value>=total)offset.value=Math.max(0,Math.floor((total-1)/limit)*limit)})
</script>
<template><div class="page-heading"><div><h1>进度视图</h1><p class="page-description">同一份任务数据，在看板、甘特和日历之间切换。</p></div><div class="view-tabs" role="group" aria-label="进度视图"><button :class="{selected:view==='board'}" @click="view='board'"><Columns3 :size="15"/>看板</button><button :class="{selected:view==='gantt'}" @click="view='gantt'"><GanttChart :size="15"/>甘特</button><button :class="{selected:view==='calendar'}" @click="view='calendar'"><CalendarDays :size="15"/>日历</button></div></div><div class="filter-bar"><select v-model="project" aria-label="进度所属项目"><option value="" disabled>选择项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model="search" class="progress-search" placeholder="搜索任务、WBS、负责人" aria-label="筛选进度任务"/><select v-model="status" aria-label="进度状态筛选"><option value="">全部状态</option><option v-for="(label,key) in taskStatuses" :key="key" :value="key">{{label}}</option></select><select v-model="assignee" aria-label="进度负责人筛选"><option value="">全部负责人</option><option v-for="person in people" :key="person">{{person}}</option></select><button class="button subtle small" :disabled="loading" @click="load"><RefreshCw :size="14"/>刷新</button></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="!project" class="surface empty-state"><GanttChart :size="36"/><h2>先选择一个项目</h2><p>进度视图使用项目完整任务树。没有项目时，请先创建项目。</p></div><p v-else-if="loading" class="loading-message">正在读取完整任务树…</p><template v-else><div class="progress-toolbar"><span>{{tasks.length}} 项任务 · 当前 {{rows.length}} 项{{filtering?'（含匹配项祖先）':''}}</span><template v-if="view!=='board'"><button class="text-button" @click="expandAll">全部展开</button><button class="text-button" :disabled="filtering" @click="foldAll">折叠汇总任务</button></template><template v-if="view!=='board'"><div class="date-navigation"><button class="icon-button" aria-label="上一个时间段" @click="shift(-1)"><ChevronLeft :size="17"/></button><input v-model="anchor" type="date" aria-label="进度参考日期"/><button class="icon-button" aria-label="下一个时间段" @click="shift(1)"><ChevronRight :size="17"/></button><button class="text-button" @click="anchor=localDate()">今天</button></div><select v-if="view==='gantt'" v-model="zoom" aria-label="甘特缩放"><option value="day">日视图</option><option value="week">周视图</option><option value="month">月视图</option></select></template></div><div v-if="view==='board'" class="task-board"><section v-for="column in statuses" :key="column" class="board-column" @dragover.prevent @drop="drop($event,column)"><h2>{{taskStatuses[column]}} <span>{{columns(column).length}}</span></h2><p v-if="!columns(column).length" class="board-empty">暂无叶子任务</p><article v-for="{task} in columns(column).slice(0,boardLimits[column]||40)" :key="task.id" class="board-task"><div class="board-task-top"><button v-if="!['done','canceled'].includes(task.status)&&!isArchived(task.project_id)" class="drag-handle" draggable="true" :aria-label="`拖动 ${task.name} 到状态列`" @dragstart="drag($event,task)" @dragend="boardDrag=undefined"><GripVertical :size="14"/></button><small>{{task.wbs_code}}</small><span>{{task.progress}}%</span></div><button class="table-title" @click="emit('task',task.id)">{{task.name}}</button><p>{{task.assignee||'未指定负责人'}} <span v-if="task.plan_end"> · {{dateLabel(task.plan_end)}} 截止</span></p><div class="progress-track"><i :style="{width:task.progress+'%'}"/></div><button v-if="task.status!=='canceled'&&!isArchived(task.project_id)" class="text-button" @click="editStatus(task)">{{task.status==='done'?'填写原因重开':'修改状态'}}</button></article><button v-if="columns(column).length>(boardLimits[column]||40)" class="button subtle small board-more" @click="boardLimits[column]=(boardLimits[column]||40)+40">再显示 40 项（尚有 {{columns(column).length-(boardLimits[column]||40)}} 项）</button></section></div><section v-else-if="view==='gantt'" class="surface gantt-surface"><div class="gantt-legend"><span><i class="plan"/>计划范围 / 完成比例</span><span><i class="actual"/>实际范围</span><span><i class="summary"/>父任务汇总</span><span><i class="today"/>今天</span><small>共加载 {{tasks.length}} 项；每页最多展示 {{limit}} 行，分页不截断数据。</small></div><div class="gantt-scroll"><div class="gantt-chart" :style="{width:(timelineWidth+310)+'px'}"><div class="gantt-header"><div class="gantt-task-header">任务 / 计划与实际</div><div class="gantt-dates" :style="{width:timelineWidth+'px'}"><span v-for="day in days" :key="day.number" :class="{weekend:day.weekend,today:day.today,'month-start':day.monthStart}" :style="{width:timeline.cell+'px'}">{{zoom==='month'?(day.monthStart?day.label:day.label.split('/')[1]):day.label}}</span></div></div><div v-for="{task,ancestor} in visibleRows" :key="task.id" class="gantt-row"><div class="gantt-task-label"><div :style="{paddingLeft:Math.min(task.depth||0,8)*13+'px'}"><button v-if="task.has_children" class="tree-toggle" :disabled="filtering" :aria-label="`折叠或展开 ${task.name}`" @click="toggle(task.id)"><ChevronRight v-if="collapsed.includes(task.id)&&!filtering" :size="13"/><ChevronDown v-else :size="13"/></button><span v-else class="tree-toggle-spacer"/><button class="gantt-name" :title="task.name" @click="emit('task',task.id)">{{task.wbs_code}} {{task.name}}</button><span class="gantt-percent">{{task.progress}}%</span></div><small>{{ancestor?'保留上级路径 · ':''}}计划 {{task.plan_start||'未设'}} 至 {{task.plan_end||'未设'}}<br/>实际 {{task.actual_start||'未开始'}} 至 {{task.actual_end||'尚无结束日期'}}</small></div><div class="gantt-track" :style="{width:timelineWidth+'px',backgroundSize:timeline.cell+'px 100%'}"><span v-for="day in days.filter(d=>d.weekend||d.today)" :key="day.number" class="gantt-day-bg" :class="{weekend:day.weekend,today:day.today}" :style="{left:(day.number-timeline.start)*timeline.cell+'px',width:timeline.cell+'px'}"/><button v-if="inWindow(task)" class="gantt-bar plan" :class="{summary:task.has_children,done:task.status==='done'}" :style="barStyle(task)" :title="`${task.name}：计划 ${task.plan_start} 至 ${task.plan_end}，完成 ${task.progress}%`" @click="emit('task',task.id)"><i :style="{width:task.progress+'%'}"/><span v-if="zoom!=='month'">{{task.has_children?'汇总 ':''}}{{task.progress}}%</span></button><button v-if="inWindow(task,true)" class="gantt-bar actual" :class="{summary:task.has_children}" :style="barStyle(task,true)" :title="`${task.name}：实际 ${task.actual_start} 至 ${task.actual_end}`" @click="emit('task',task.id)"/><button v-else-if="task.actual_start&&pointInWindow(task.actual_start)" class="actual-start-dot" :style="pointStyle(task.actual_start)" :title="`实际开始 ${task.actual_start}，结束日期未记录`" :aria-label="`${task.name} 实际开始 ${task.actual_start}`" @click="emit('task',task.id)"/></div></div></div></div><div v-if="!rows.length" class="empty-state compact"><p>没有符合筛选条件的任务。</p></div><Pager :offset="offset" :limit="limit" :total="rows.length" @change="page"/></section><section v-else class="surface calendar-surface"><div class="section-heading"><h2>{{monthTitle}}</h2><span class="input-hint">按计划起止范围展示，点击任务打开详情</span></div><div class="calendar-scroll"><div class="task-calendar"><div v-for="label in ['周一','周二','周三','周四','周五','周六','周日']" :key="label" class="calendar-weekday">{{label}}</div><div v-for="day in calendarDays" :key="day.day" class="calendar-day" :class="{outside:day.outside,today:day.today}"><strong>{{day.label}}<span v-if="day.today">今天</span></strong><button v-for="{task} in day.tasks.slice(0,4)" :key="task.id" class="calendar-task" :class="{summary:task.has_children,done:task.status==='done'}" :title="`${task.name} · ${task.progress}% · ${task.plan_start} 至 ${task.plan_end}`" @click="emit('task',task.id)">{{task.wbs_code}} {{task.name}}</button><button v-if="day.tasks.length>4" class="calendar-more" @click="openCalendarDay(day)">另有 {{day.tasks.length-4}} 项，查看全部</button></div></div></div></section><section v-if="view!=='board'&&missing.length" class="surface missing-schedule"><div class="section-heading"><h2>计划日期待补充 <span class="count">{{missing.length}}</span></h2><span class="input-hint">缺少开始或结束日期，单独列出</span></div><ul><li v-for="{task} in missing" :key="task.id"><button class="table-title" @click="emit('task',task.id)">{{task.wbs_code}} {{task.name}}</button><span>{{task.plan_start||'未设开始'}} 至 {{task.plan_end||'未设结束'}}</span><span>{{taskStatuses[task.status]}} {{task.progress}}%</span></li></ul></section></template><Modal :open="!!changing" :title="changing?.status==='done'?'重开已完成叶子任务':'修改叶子任务状态'" @close="!saving&&(changing=undefined)"><form class="modal-body" @submit.prevent="saveStatus"><p class="onboarding-intro">{{changing?.name}}</p><label v-if="changing?.status==='done'">重开原因<textarea v-model="reason" rows="3" required placeholder="说明需要再次跟进的原因"/></label><label v-else>新状态<select v-model="nextStatus"><option v-for="(label,key) in taskStatuses" :key="key" :value="key">{{label}}</option></select></label><p class="input-hint">父任务的进度与状态由子任务汇总。已完成任务重开后为进行中、进度 0%，原因写入历史。</p><ConflictNotice :value="conflict.current.value" @keep="conflict.clear()" @reload="reloadConflict"/><p v-if="changeError" class="form-error" role="alert">{{changeError}}</p><div class="modal-footer"><button class="button primary" :disabled="saving">{{saving?'保存中…':'确认保存'}}</button></div></form></Modal><Modal :open="!!calendarSelected" :title="`${calendarSelected?.date||''} 计划任务`" wide @close="calendarSelected=undefined"><div class="modal-body"><p class="input-hint">共 {{calendarSelected?.tasks.length||0}} 项，按完整项目树顺序展示。</p><ul class="calendar-day-detail"><li v-for="{task} in calendarSelected?.tasks.slice(calendarOffset,calendarOffset+30)||[]" :key="task.id"><button class="table-title" @click="emit('task',task.id)">{{task.wbs_code}} {{task.name}}</button><span>{{task.assignee||'未指定'}} · {{taskStatuses[task.status]}} {{task.progress}}%</span><small>{{task.plan_start}} 至 {{task.plan_end}}</small></li></ul><Pager :offset="calendarOffset" :limit="30" :total="calendarSelected?.tasks.length||0" @change="calendarOffset=$event"/></div></Modal></template>
